type PendingToolContext = {
  runId: string;
  name: string;
  input: any;
};

type SecretEntry = {
  value: string;
  expiresAt?: number;
  enc?: {
    alg: 'aes-256-gcm';
    ivB64: string;
    tagB64: string;
  };
};

const sessionSecrets = new Map<string, Map<string, SecretEntry>>();
const pendingToolBySession = new Map<string, PendingToolContext>();
const runConfigBySession = new Map<
  string,
  {
    provider?: string;
    apiKey?: string;
    baseUrl?: string;
    model?: string;
    kind?: 'chat' | 'agent';
    browserSessionId?: string;
    autoApproveAll?: boolean;
    autoApproveSafe?: boolean;
    expiresAt: number;
  }
>();

function nowMs() {
  return Date.now();
}

function getMasterKeyBytes(): Buffer | null {
  const raw = String(process.env.SECRETS_MASTER_KEY || process.env.JWT_SECRET || '').trim();
  if (!raw) return null;
  const crypto = require('crypto') as typeof import('crypto');
  return crypto.createHash('sha256').update(raw, 'utf8').digest();
}

function encrypt(value: string) {
  const key = getMasterKeyBytes();
  if (!key) return null;
  const crypto = require('crypto') as typeof import('crypto');
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  const c1 = cipher.update(value, 'utf8');
  const c2 = cipher.final();
  const tag = cipher.getAuthTag();
  const buf = Buffer.concat([c1, c2]);
  return { value: buf.toString('base64'), ivB64: iv.toString('base64'), tagB64: tag.toString('base64') };
}

function decrypt(entry: SecretEntry): string | null {
  if (!entry.enc) return entry.value;
  const key = getMasterKeyBytes();
  if (!key) return null;
  const crypto = require('crypto') as typeof import('crypto');
  const iv = Buffer.from(entry.enc.ivB64, 'base64');
  const tag = Buffer.from(entry.enc.tagB64, 'base64');
  const decipher = crypto.createDecipheriv(entry.enc.alg, key, iv);
  decipher.setAuthTag(tag);
  const c1 = decipher.update(Buffer.from(entry.value, 'base64'));
  const c2 = decipher.final();
  return Buffer.concat([c1, c2]).toString('utf8');
}

export async function setUserSecretEncrypted(
  userId: string,
  provider: string,
  key: string,
  value: string
) {
  const uid = String(userId || '').trim();
  const p = String(provider || '').trim();
  const k = String(key || '').trim();
  if (!uid || !p || !k) return;

  const { UserSecret } = await import('../models/userSecret');
  const enc = encrypt(String(value ?? ''));
  const doc: any = {
    userId: uid,
    provider: p,
    key: k,
  };
  if (enc) {
    doc.value = enc.value;
    doc.enc = { alg: 'aes-256-gcm', ivB64: enc.ivB64, tagB64: enc.tagB64 };
  } else {
    doc.value = String(value ?? '');
    doc.enc = undefined;
  }
  await UserSecret.findOneAndUpdate({ userId: uid, provider: p, key: k }, { $set: doc }, { upsert: true, new: true });
}

export async function getUserSecret(
  userId: string,
  provider: string,
  key: string
): Promise<string | null> {
  const uid = String(userId || '').trim();
  const p = String(provider || '').trim();
  const k = String(key || '').trim();
  if (!uid || !p || !k) return null;
  const { UserSecret } = await import('../models/userSecret');
  const doc: any = await UserSecret.findOne({ userId: uid, provider: p, key: k })
    .select({ value: 1, enc: 1 })
    .lean();
  if (!doc || typeof doc.value !== 'string') return null;
  const entry: any = { value: doc.value };
  if (doc.enc && typeof doc.enc === 'object') {
    entry.enc = {
      alg: doc.enc.alg,
      ivB64: doc.enc.ivB64,
      tagB64: doc.enc.tagB64,
    };
  }
  const plain = decrypt(entry);
  return plain ?? null;
}

function purgeExpired(bucket: Map<string, SecretEntry>) {
  const now = nowMs();
  for (const [k, v] of bucket.entries()) {
    if (typeof v.expiresAt === 'number' && v.expiresAt > 0 && v.expiresAt <= now) bucket.delete(k);
  }
}

export function setSessionSecret(sessionId: string, key: string, value: string) {
  const sid = String(sessionId || '').trim();
  const k = String(key || '').trim();
  if (!sid || !k) return;
  let bucket = sessionSecrets.get(sid);
  if (!bucket) {
    bucket = new Map<string, SecretEntry>();
    sessionSecrets.set(sid, bucket);
  }
  purgeExpired(bucket);
  bucket.set(k, { value });
}

export function getSessionSecret(sessionId: string, key: string): string | null {
  const sid = String(sessionId || '').trim();
  const k = String(key || '').trim();
  if (!sid || !k) return null;
  const bucket = sessionSecrets.get(sid);
  if (!bucket) return null;
  purgeExpired(bucket);
  const entry = bucket.get(k);
  if (!entry) return null;
  if (typeof entry.expiresAt === 'number' && entry.expiresAt > 0 && entry.expiresAt <= nowMs()) {
    bucket.delete(k);
    return null;
  }
  const plain = decrypt(entry);
  return plain ?? null;
}

export function clearSessionSecrets(sessionId: string) {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  sessionSecrets.delete(sid);
}

export function setSessionSecretEncrypted(sessionId: string, key: string, value: string, ttlSeconds?: number) {
  const sid = String(sessionId || '').trim();
  const k = String(key || '').trim();
  if (!sid || !k) return null;
  let bucket = sessionSecrets.get(sid);
  if (!bucket) {
    bucket = new Map<string, any>();
    sessionSecrets.set(sid, bucket);
  }
  purgeExpired(bucket as any);

  const ttl = typeof ttlSeconds === 'number' && Number.isFinite(ttlSeconds) && ttlSeconds > 0 ? ttlSeconds : undefined;
  const expiresAt = ttl ? nowMs() + ttl * 1000 : undefined;

  const enc = encrypt(String(value ?? ''));
  if (enc) {
    bucket.set(k, { value: enc.value, expiresAt, enc: { alg: 'aes-256-gcm', ivB64: enc.ivB64, tagB64: enc.tagB64 } });
  } else {
    bucket.set(k, { value: String(value ?? ''), expiresAt });
  }
  return expiresAt ?? null;
}

export function setPendingTool(sessionId: string, ctx: PendingToolContext) {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  pendingToolBySession.set(sid, ctx);
}

export function popPendingTool(sessionId: string): PendingToolContext | null {
  const sid = String(sessionId || '').trim();
  if (!sid) return null;
  const ctx = pendingToolBySession.get(sid) || null;
  pendingToolBySession.delete(sid);
  return ctx;
}

export function setSessionRunConfig(
  sessionId: string,
  cfg: {
    provider?: string;
    apiKey?: string;
    baseUrl?: string;
    model?: string;
    kind?: 'chat' | 'agent';
    browserSessionId?: string;
    autoApproveAll?: boolean;
    autoApproveSafe?: boolean;
    ttlSeconds?: number;
  }
) {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  const ttlSeconds =
    typeof cfg.ttlSeconds === 'number' && Number.isFinite(cfg.ttlSeconds) && cfg.ttlSeconds > 0
      ? cfg.ttlSeconds
      : 15 * 60;
  runConfigBySession.set(sid, {
    provider: cfg.provider,
    apiKey: cfg.apiKey,
    baseUrl: cfg.baseUrl,
    model: cfg.model,
    kind: cfg.kind,
    browserSessionId: cfg.browserSessionId,
    autoApproveAll: cfg.autoApproveAll,
    autoApproveSafe: cfg.autoApproveSafe,
    expiresAt: nowMs() + ttlSeconds * 1000,
  });
}

export function getSessionRunConfig(sessionId: string) {
  const sid = String(sessionId || '').trim();
  if (!sid) return null;
  const cur = runConfigBySession.get(sid) || null;
  if (!cur) return null;
  if (typeof cur.expiresAt === 'number' && cur.expiresAt > 0 && cur.expiresAt <= nowMs()) {
    runConfigBySession.delete(sid);
    return null;
  }
  return cur;
}

import { MemoryItem } from '../models/memoryItem';
import OpenAI from 'openai';

const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY || 'dummy',
  baseURL: process.env.OPENAI_BASE_URL,
});

export class MemoryService {
  static async searchMemories(userId: string, text: string, limit = 5): Promise<string[]> {
    if (!userId) return [];

    const normalized = String(text || '')
      .normalize('NFKC')
      .toLowerCase()
      .replace(/[^\p{L}\p{N}\s]/gu, ' ');

    const keywords = normalized
      .split(/\s+/)
      .map(w => w.trim())
      .filter(w => w.length >= 2)
      .slice(0, 12);

    if (keywords.length === 0) {
      const items = await MemoryItem.find({ userId, scope: 'user' })
        .sort({ updatedAt: -1 })
        .limit(limit);
      return items.map(item => `${item.key}: ${typeof item.value === 'string' ? item.value : JSON.stringify(item.value)}`);
    }

    const escaped = keywords.map(k => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
    const regex = new RegExp(escaped.join('|'), 'i');

    const items = await MemoryItem.find({
      userId,
      scope: 'user',
      $or: [
        { key: { $regex: regex } },
        { value: { $regex: regex } }
      ]
    })
    .sort({ updatedAt: -1 })
    .limit(limit);

    if (items.length === 0) {
      const fallback = await MemoryItem.find({ userId, scope: 'user' })
        .sort({ updatedAt: -1 })
        .limit(limit);
      return fallback.map(item => `${item.key}: ${typeof item.value === 'string' ? item.value : JSON.stringify(item.value)}`);
    }

    return items.map(item => `${item.key}: ${typeof item.value === 'string' ? item.value : JSON.stringify(item.value)}`);
  }

  static async extractAndSaveMemories(userId: string, userText: string, options?: any) {
    if (!userId || !userText) return;

    try {
      let client = openai;
      if (options?.apiKey) {
        client = new OpenAI({
          apiKey: options.apiKey,
          baseURL: options.baseUrl || process.env.OPENAI_BASE_URL,
        });
      }

      const completion = await client.chat.completions.create({
        model: options?.model || 'gpt-4o',
        messages: [
          {
            role: 'system',
            content: `You are a Memory Extractor. Your job is to extract permanent user facts from the conversation.

Rules:
- Extract ONLY facts that are useful to remember for future conversations (e.g., name, preferences, tech stack, job, specific instructions).
- Ignore transient info (e.g., "write a function", "fix this bug").
- Output a JSON object with a "facts" array. Each fact has "key" (short category) and "value" (the fact).
- If no relevant facts, return empty array.

Example:
User: "I am a React developer and I hate TypeScript."
Output: { "facts": [{ "key": "role", "value": "React Developer" }, { "key": "preference", "value": "Dislikes TypeScript" }] }
`
          },
          { role: 'user', content: userText }
        ],
        response_format: { type: 'json_object' }
      });

      const content = completion.choices[0].message.content;
      if (!content) return;

      const result = JSON.parse(content);
      if (result.facts && Array.isArray(result.facts)) {
        for (const fact of result.facts) {
          // Check if fact already exists to avoid dupes (naive check)
          const exists = await MemoryItem.findOne({
            userId,
            scope: 'user',
            key: fact.key,
            value: fact.value
          });

          if (!exists) {
            await MemoryItem.create({
              scope: 'user',
              userId,
              key: fact.key,
              value: fact.value,
              sessionId: options?.sessionId // Optional link to origin session
            });
            // console.info(`[Memory] Saved fact: ${fact.key} = ${fact.value}`);
          }
        }
      }

    } catch (err) {
      console.error('[Memory] Extraction failed:', err);
    }
  }
}

import fs from 'fs';
import path from 'path';
import { v4 as uuidv4 } from 'uuid';
import pdf from 'pdf-parse';

const DATA_DIR = process.env.DATA_DIR || path.join(process.cwd(), 'data');
const KNOWLEDGE_FILE = path.join(DATA_DIR, 'knowledge.json');

// Ensure directory exists (sync is fine at startup, or make it async if called later)
if (!fs.existsSync(DATA_DIR)) {
    try { fs.mkdirSync(DATA_DIR, { recursive: true }); } catch { }
}

export interface Document {
    id: string;
    filename: string;
    content: string;
    tags: string[];
    createdAt: number;
    embedding?: number[]; // Placeholder for future
}

// Load knowledge base
async function loadKnowledge(): Promise<Document[]> {
    try {
        await fs.promises.access(KNOWLEDGE_FILE);
        const data = await fs.promises.readFile(KNOWLEDGE_FILE, 'utf-8');
        return JSON.parse(data);
    } catch {
        return [];
    }
}

// Save knowledge base
async function saveKnowledge(docs: Document[]) {
    await fs.promises.writeFile(KNOWLEDGE_FILE, JSON.stringify(docs, null, 2));
}

export const KnowledgeService = {
    getAll: async () => await loadKnowledge(),

    add: async (filename: string, content: string, tags: string[] = []) => {
        console.log(`[KnowledgeService] Adding: ${filename}`);
        const docs = await loadKnowledge();
        const newDoc: Document = {
            id: uuidv4(),
            filename,
            content,
            tags,
            createdAt: Date.now()
        };
        docs.push(newDoc);
        try {
            await saveKnowledge(docs);
            console.log(`[KnowledgeService] Saved ${docs.length} docs.`);
        } catch (e) {
            console.error('[KnowledgeService] Save failed', e);
        }
        return newDoc;
    },

    delete: async (id: string) => {
        const docs = await loadKnowledge();
        const filtered = docs.filter(d => d.id !== id);
        await saveKnowledge(filtered);
    },

    search: async (query: string): Promise<{ document: Document, score: number, snippet: string }[]> => {
        console.log(`[KnowledgeService] Searching: ${query}`);
        const docs = await loadKnowledge();
        console.log(`[KnowledgeService] Docs in DB: ${docs.length}`);
        const q = query.toLowerCase();

        // Simple keyword scoring
        const results = docs.map(doc => {
            const text = doc.content.toLowerCase();
            const filename = doc.filename.toLowerCase();
            let score = 0;

            // Exact phrase match
            if (text.includes(q)) score += 10;
            if (filename.includes(q)) score += 5;

            // Token match
            const tokens = q.split(/\s+/);
            let matches = 0;
            tokens.forEach(t => {
                if (text.includes(t)) matches++;
            });

            score += matches;

            // Find snippet
            const idx = text.indexOf(q.split(' ')[0]);
            const start = Math.max(0, idx - 50);
            const snippet = doc.content.substring(start, start + 300) + '...';

            return { document: doc, score, snippet };
        });

        // Normalize scores roughly 0-1
        return results
            .filter(r => r.score > 0)
            .sort((a, b) => b.score - a.score)
            .map(r => ({ ...r, score: Math.min(r.score / 10, 1) })); // Simple normalization assumption
    },

    parsePDF: async (buffer: Buffer): Promise<string> => {
        try {
            const data = await pdf(buffer);
            return data.text;
        } catch (e) {
            console.error('PDF Parse Error', e);
            throw new Error('Failed to parse PDF');
        }
    }
};

