    return new Promise<void>((resolve, reject) => {
        const ws = new WebSocket(wsUrl);
        const timeout = setTimeout(() => {
            console.error('❌ Timeout waiting for stream events');
            ws.close();
            reject(new Error('Timeout'));
        }, 10000); // Increased timeout

        ws.on('open', async () => {
