export class JsonQueryTool extends BaseTool {
    name = 'json_query';
    description = 'Query a specific value from a JSON object using dot notation path.';
    version = '1.0.0';
    tags = ['data', 'json'];
    inputSchema = { type: 'object' as const, properties: { json: { type: 'object' }, path: { type: 'string' } }, required: ['json', 'path'] };
    outputSchema = { type: 'object' as const, properties: { value: { type: 'any' } } };
    permissions: ToolPermission[] = [];
    sideEffects: ToolPermission[] = [];

    async execute(input: any) {
        const data = input.json;
        const pathStr = String(input.path || '');
        if (!data) return { ok: false, error: 'json required', logs: [] };

        try {
            const parts = pathStr.split('.').filter(Boolean);
            let current = data;
            for (const p of parts) {
                if (current && typeof current === 'object') {
                    current = current[p];
                } else {
                    current = undefined;
                    break;
                }
            }
            return { ok: true, output: { value: current }, logs: [] };
        } catch (e: any) {
            return { ok: false, error: e.message, logs: [] };
        }
    }
}

import { BaseTool } from '../base';
import { ToolPermission } from '../types';
import fs from 'fs';
import path from 'path';

export class CodebaseOutlineTool extends BaseTool {
    name = 'codebase_outline';
    description = 'Scan a file and extract its structure (Classes, Functions, Interfaces) using fast regex pattern matching.';
    version = '1.0.0';
    tags = ['code', 'analysis', 'outline'];
    inputSchema = {
        type: 'object' as const,
        properties: {
            filePath: { type: 'string', description: 'Absolute path or relative path to the file.' }
        },
        required: ['filePath']
    };
    outputSchema = {
        type: 'object' as const,
        properties: {
            classes: { type: 'array' },
            functions: { type: 'array' },
            interfaces: { type: 'array' },
            imports: { type: 'array' },
            totalLines: { type: 'number' }
        }
    };
    permissions: ToolPermission[] = ['read'];
    sideEffects: ToolPermission[] = [];
    rateLimitPerMinute = 60;
    auditFields = ['filePath'];

    async execute(input: any) {
        const filePath = String(input.filePath || '');
        if (!filePath) return { ok: false, error: 'filePath is required', logs: [] };

        const root = process.cwd();
        const fullPath = path.isAbsolute(filePath) ? filePath : path.resolve(root, filePath);

        if (!fs.existsSync(fullPath)) return { ok: false, error: `File not found: ${fullPath}`, logs: [] };

        try {
            const content = fs.readFileSync(fullPath, 'utf-8');
            const lines = content.split('\n');
            const outline = {
                classes: [] as string[],
                functions: [] as string[],
                interfaces: [] as string[],
                imports: [] as string[],
                totalLines: lines.length
            };

            // Regex patterns (simplified for speed)
            const patterns = {
                class: /^\s*(?:export\s+)?(?:abstract\s+)?class\s+([a-zA-Z0-9_]+)/,
                func: /^\s*(?:export\s+)?(?:async\s+)?function\s+([a-zA-Z0-9_]+)/,
                funcConst: /^\s*(?:export\s+)?const\s+([a-zA-Z0-9_]+)\s*=\s*(?:async\s*)?(?:\([^)]*\)|[a-zA-Z0-9_]+)\s*=>/,
                interface: /^\s*(?:export\s+)?interface\s+([a-zA-Z0-9_]+)/,
                import: /^\s*import\s/
            };

            lines.forEach((line, idx) => {
                const num = idx + 1;
                const trimmed = line.trim();

                let match = trimmed.match(patterns.class);
                if (match) { outline.classes.push(`L${num}: ${match[1]}`); return; }

                match = trimmed.match(patterns.func);
                if (match) { outline.functions.push(`L${num}: ${match[1]}`); return; }

                match = trimmed.match(patterns.funcConst);
                if (match) { outline.functions.push(`L${num}: ${match[1]}`); return; }

                match = trimmed.match(patterns.interface);
                if (match) { outline.interfaces.push(`L${num}: ${match[1]}`); return; }

                match = trimmed.match(patterns.import);
                if (match) { outline.imports.push(`L${num}: ${trimmed.substring(0, 50)}...`); return; }
            });

            return {
                ok: true,
                output: outline,
                logs: [`Scanned ${filePath}: ${outline.classes.length} classes, ${outline.functions.length} functions.`]
            };

        } catch (e: any) {
            return { ok: false, error: `Failed to read file: ${e.message}`, logs: [] };
        }
    }
}

import path from 'path';
import fs from 'fs';
import { glob } from 'glob';
import { VectorMemory } from '../../memory/VectorMemory';

let memory: VectorMemory | null = null;

export const CodebaseNavigatorTool = {
    name: 'codebase_navigator',
    version: '2.0.0', // Major bump for God Mode
    tags: ['search', 'codebase', 'semantic', 'memory', 'scalable'],
    description: 'Semantically index and search the codebase. Use this to find relevant code snippets via natural language queries. Optimized for large codebases.',
    inputSchema: {
        type: 'object',
        properties: {
            action: {
                type: 'string',
                enum: ['index', 'search'],
                description: 'Action to perform: "index" to scan files, "search" to query memory.'
            },
            targetDir: {
                type: 'string',
                description: 'Directory to index (absolute path). Required for "index".'
            },
            query: {
                type: 'string',
                description: 'Natural language query. Required for "search".'
            },
            limit: {
                type: 'number',
                default: 5,
                description: 'Number of results to return.'
            },
            pattern: {
                type: 'string',
                default: '**/*.{ts,tsx,js,jsx,py,md,java,go,rs}',
                description: 'Glob pattern for indexing.'
            }
        },
        required: ['action']
    },
    outputSchema: {
        type: 'object',
        properties: {
            ok: { type: 'boolean' },
            output: { type: 'object' },
            logs: { type: 'array' }
        }
    },
    permissions: ['read', 'internet'],
    sideEffects: ['read'],
    rateLimitPerMinute: 10,
    auditFields: ['action', 'query', 'targetDir'],
    mockSupported: false,

    execute: async (input: { action: string, targetDir?: string, query?: string, limit?: number, pattern?: string }) => {
        if (!memory) {
            memory = new VectorMemory();
        }
        await memory.init();

        if (input.action === 'index') {
            if (!input.targetDir) throw new Error('targetDir is required for index action');
            const targetDir = input.targetDir;
            const pattern = input.pattern || '**/*.{ts,tsx,js,jsx,py,md,java,go,rs}';

            console.log(`[Navigator] Indexing ${targetDir} with pattern ${pattern}...`);
            const logs: string[] = [];

            // Use glob to find files efficiently
            // ignore node_modules, dist, etc.
            const files = await glob(pattern, {
                cwd: targetDir,
                ignore: ['**/node_modules/**', '**/dist/**', '**/coverage/**', '**/.git/**'],
                nodir: true,
                absolute: true
            });

            console.log(`[Navigator] Found ${files.length} files.`);
            logs.push(`Found ${files.length} files.`);

            let count = 0;
            // Process in chunks or sequentially to avoid OOM
            // For now sequential is fine for < 100k files if we don't hold content in memory
            for (const fullPath of files) {
                try {
                    const content = fs.readFileSync(fullPath, 'utf-8');
                    // Skip huge files
                    if (content.length > 100000) {
                        logs.push(`Skipped large file: ${path.basename(fullPath)}`);
                        continue;
                    }

                    // Chunk large files into multiple vectors for better search
                    if (content.length > 5000) {
                        const chunkSize = 5000;
                        for (let i = 0; i < content.length; i += chunkSize) {
                            const chunk = content.substring(i, i + chunkSize);
                            await memory.add(`${fullPath}#chunk${Math.floor(i / chunkSize)}`, chunk, {
                                type: 'code',
                                path: fullPath,
                                chunkIndex: Math.floor(i / chunkSize)
                            });
                        }
                    } else {
                        await memory.add(fullPath, content, { type: 'code', path: fullPath });
                    }
                    count++;
                } catch (err: any) {
                    // Ignore read errors
                    logs.push(`Failed to read ${path.basename(fullPath)}: ${err.message}`);
                }
            }

            return { ok: true, output: { message: `Indexed ${count} files.` }, logs };
        }

        if (input.action === 'search') {
            if (!input.query) throw new Error('query is required for search action');

            console.log(`[Navigator] Searching for: "${input.query}"`);
            const results = await memory.search(input.query, input.limit || 5);

            // Format results for the agent
            const snippets = results.ids[0].map((id: string, idx: number) => ({
                filePath: id,
                score: results.distances[0][idx],
                preview: (results.documents[0][idx] || '').substring(0, 300) + '...'
            }));

            return { ok: true, output: { results: snippets }, logs: [] };
        }

        throw new Error(`Unknown action: ${input.action}`);
    }
};

import { ToolDefinition } from '../types';
import { callLLM } from '../../llm';
import fs from 'fs';
import path from 'path';

/**
 * CodeReviewerTool - AI-powered code review
 * Analyzes code for best practices, code smells, and improvement suggestions
 */
export class CodeReviewerTool implements ToolDefinition {
    name = 'code_reviewer';
    version = '1.0.0';
    description = 'AI-powered code review for quality, best practices, and improvements';
    tags = ['review', 'quality', 'ai'];

    inputSchema = {
        type: 'object' as const,
        properties: {
            files: {
                type: 'array' as const,
                items: { type: 'string' as const },
                description: 'List of file paths to review'
            },
            projectPath: {
                type: 'string' as const,
                description: 'Base project path'
            },
            reviewType: {
                type: 'string' as const,
                enum: ['quick', 'detailed', 'comprehensive'],
                description: 'Type of review'
            }
        },
        required: ['files']
    };

    outputSchema = {
        type: 'object' as const,
        properties: {
            overallScore: { type: 'number' as const },
            issues: {
                type: 'array' as const,
                items: { type: 'object' as const }
            },
            suggestions: {
                type: 'array' as const,
                items: { type: 'object' as const }
            }
        }
    };

    permissions = ['read' as const];
    sideEffects = [];
    rateLimitPerMinute = 10;
    auditFields = ['projectPath'];
    mockSupported = false;

    async execute(input: { files: string[]; projectPath?: string; reviewType?: string }) {
        const { files, projectPath = '.', reviewType = 'detailed' } = input;
        const logs: string[] = [];

        try {
            logs.push(`Reviewing ${files.length} files with ${reviewType} review`);

            const issues: any[] = [];
            const suggestions: any[] = [];
            let totalScore = 0;

            for (const file of files.slice(0, 5)) { // Limit to 5 files for performance
                const filePath = path.isAbsolute(file) ? file : path.resolve(projectPath, file);

                if (!fs.existsSync(filePath)) {
                    logs.push(`File not found: ${filePath}`);
                    continue;
                }

                const content = fs.readFileSync(filePath, 'utf-8');
                const review = await this.reviewFile(filePath, content, reviewType);

                issues.push(...review.issues);
                suggestions.push(...review.suggestions);
                totalScore += review.score;

                logs.push(`Reviewed: ${file} (Score: ${review.score}/100)`);
            }

            const overallScore = files.length > 0 ? Math.round(totalScore / Math.min(files.length, 5)) : 0;

            logs.push(`Review complete. Overall score: ${overallScore}/100`);

            return {
                ok: true,
                output: {
                    overallScore,
                    filesReviewed: Math.min(files.length, 5),
                    issues,
                    suggestions,
                    summary: {
                        critical: issues.filter(i => i.severity === 'critical').length,
                        warning: issues.filter(i => i.severity === 'warning').length,
                        info: issues.filter(i => i.severity === 'info').length
                    }
                },
                logs
            };

        } catch (error: any) {
            logs.push(`Error: ${error.message}`);
            return {
                ok: false,
                error: error.message,
                logs
            };
        }
    }

    private async reviewFile(filePath: string, content: string, reviewType: string): Promise<any> {
        const ext = path.extname(filePath);
        const language = this.detectLanguage(ext);

        const reviewPrompt = `You are an expert code reviewer. Review the following ${language} code and provide feedback.

FILE: ${path.basename(filePath)}
CODE:
\`\`\`${language}
${content.slice(0, 2000)}
\`\`\`

Provide your review in JSON format:
{
  "score": <0-100>,
  "issues": [
    {
      "line": <line_number>,
      "severity": "critical|warning|info",
      "category": "best-practice|code-smell|naming|complexity",
      "message": "description"
    }
  ],
  "suggestions": [
    {
      "category": "performance|readability|maintainability",
      "message": "suggestion"
    }
  ]
}

Focus on: best practices, code smells, naming conventions, complexity.
Return ONLY valid JSON.`;

        try {
            const response = await callLLM(reviewPrompt, [
                { role: 'system', content: 'You are a code review expert. Return only valid JSON.' }
            ]);

            const jsonMatch = response.match(/\{[\s\S]*\}/);
            const jsonStr = jsonMatch ? jsonMatch[0] : response;
            const review = JSON.parse(jsonStr);

            return {
                score: review.score || 70,
                issues: Array.isArray(review.issues) ? review.issues : [],
                suggestions: Array.isArray(review.suggestions) ? review.suggestions : []
            };
        } catch (error) {
            // Fallback to basic review
            return this.basicReview(content);
        }
    }

    private basicReview(content: string): any {
        const issues: any[] = [];
        const lines = content.split('\n');

        // Basic checks
        if (content.includes('console.log')) {
            issues.push({
                severity: 'warning',
                category: 'best-practice',
                message: 'Remove console.log statements in production code'
            });
        }

        if (content.includes('var ')) {
            issues.push({
                severity: 'warning',
                category: 'best-practice',
                message: 'Use const/let instead of var'
            });
        }

        if (lines.length > 500) {
            issues.push({
                severity: 'info',
                category: 'complexity',
                message: 'File is very long. Consider splitting into smaller modules.'
            });
        }

        return {
            score: 75 - (issues.length * 5),
            issues,
            suggestions: [
                { category: 'maintainability', message: 'Consider adding more comments' }
            ]
        };
    }

    private detectLanguage(ext: string): string {
        const langMap: Record<string, string> = {
            '.js': 'javascript',
            '.ts': 'typescript',
            '.jsx': 'javascript',
            '.tsx': 'typescript',
            '.py': 'python',
            '.java': 'java',
            '.go': 'go',
            '.rs': 'rust'
        };
        return langMap[ext] || 'text';
    }
}

